// Token pipeline: renders the TypeScript theme in
// projects/components/src/lib/tokens/ into the two generated files the rest
// of the workspace consumes —
//
//   src/lib/styles/_tokens.scss   the `:root` custom properties, the responsive
//                                 retunes and the zeroed durations under
//                                 prefers-reduced-motion: reduce
//   src/lib/tokens/tokens.ts      the typed `tokens` object (`var(--name)` per key)
//
// Usage (from frontend/):  npm run tokens          regenerate
//                          npm run tokens:check    fail if any file is stale (CI)
//
// Node strips the token sources' TypeScript types natively; the resolve hook
// only adds the `.ts` extension Angular-style imports leave off.
import { readFileSync, writeFileSync } from 'node:fs';
import { registerHooks } from 'node:module';
import { dirname, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import prettier from 'prettier';

registerHooks({
  resolve(specifier, context, next) {
    if (specifier.startsWith('.') && !/\.[cm]?[jt]s$/.test(specifier)) {
      return next(`${specifier}.ts`, context);
    }
    return next(specifier, context);
  },
});

const here = dirname(fileURLToPath(import.meta.url));
const lib = resolve(here, '../projects/components/src/lib');
const load = (path) => import(pathToFileURL(resolve(lib, path)).href);

const { seedlingLightTheme, responsiveOverrides, reducedMotionOverride } =
  await load('tokens/themes/index.ts');
const { themeToCss } = await load('tokens/themeToCss.ts');
const { themeToTokensObject } = await load('tokens/themeToTokensObject.ts');

const header = (comment) => `// !!! DO NOT EDIT !!!
// Generated by \`npm run tokens\` from projects/components/src/lib/tokens/.
// Change the TypeScript theme and regenerate.
//
${comment}
`;

const scss =
  header(`// Components consume these as CSS custom properties (\`var(--colorNeutralForeground1)\`
// etc.), named exactly as the theme keys — the Fluent UI v9 convention. Never
// hard-code a hex value in a component stylesheet — if a colour is missing,
// add an alias token to the theme first.
//
// Breakpoints live SCSS-side in \`_breakpoints.scss\` (\`$bp-tablet\` /
// \`$bp-desktop\` + the \`respond-to()\` mixin).`) +
  '\n' +
  themeToCss(seedlingLightTheme, [...responsiveOverrides, reducedMotionOverride]);

const tokensTs =
  header(`// \`tokens.colorBrandBackground === 'var(--colorBrandBackground)'\`: read a token
// from TypeScript (stories, inline style bindings) without repeating its name.`) +
  `
import type { Theme } from './types';

export const tokens: Record<keyof Theme, string> = ${JSON.stringify(themeToTokensObject(seedlingLightTheme), null, 2)};
`;

const outputs = [
  { path: resolve(lib, 'styles/_tokens.scss'), text: scss, parser: 'scss' },
  { path: resolve(lib, 'tokens/tokens.ts'), text: tokensTs, parser: 'typescript' },
];

const check = process.argv.includes('--check');
let stale = 0;
for (const { path, text, parser } of outputs) {
  const options = { ...(await prettier.resolveConfig(path)), parser };
  const formatted = await prettier.format(text, options);
  let current = '';
  try {
    current = readFileSync(path, 'utf8');
  } catch {
    current = '';
  }
  if (current === formatted) continue;
  if (check) {
    console.error(`stale: ${path} — run \`npm run tokens\` in frontend/`);
    stale++;
  } else {
    writeFileSync(path, formatted);
    console.log(`wrote ${path}`);
  }
}
process.exit(stale ? 1 : 0);
